import * as React from 'react';
import { CommonProps } from '../utility/commonProps';
export interface TabNavigationProps extends Omit<React.ComponentPropsWithoutRef<'nav'>, 'className' | 'style'>, CommonProps {
    /**
     * The content for the tab navigation.
     */
    children: React.ReactNode;
}
/**
 * Tab Navigation allows for page-level navigation between sets of content, typically used at the top of the screen.
 *
 * {@link https://livingdesign.walmart.com/components/tab-navigation/ Guidelines}
 * {@link https://livingdesign.walmart.com/components/tab-navigation/react/ React documentation}
 *
 * ### Content
 *
 * Tab Navigation's accepts Tab Navigation Items through the `children` prop:
 *
 * ```tsx
 * <TabNavigation>
 *   <TabNavigationItem href="/1/">One</TabNavigationItem>
 *   <TabNavigationItem href="/2/">Two</TabNavigationItem>
 *   <TabNavigationItem href="/3/">Three</TabNavigationItem>
 * </TabNavigation>
 * ```
 */
export declare const TabNavigation: React.FunctionComponent<TabNavigationProps>;
